#!/usr/bin/env python3
"""Compile Sources/HeatPumpKit/Knowledge/*.md into Swift string constants.

The markdown files stay the editable source. Run this after editing them:
    python3 Packages/HeatPumpKit/scripts/generate-knowledge.py
A unit test fails when the generated file is out of date.
"""
import pathlib

root = pathlib.Path(__file__).resolve().parent.parent
source = root / "Sources/HeatPumpKit/Knowledge"
target = root / "Sources/HeatPumpKit/Support/KnowledgeContent.generated.swift"

lines = [
    "// Generated by scripts/generate-knowledge.py from Sources/HeatPumpKit/Knowledge/*.md. Do not edit.",
    "",
    "enum KnowledgeContent {",
    "    static let documents: [String: String] = [",
]
for path in sorted(source.glob("*.md")):
    text = path.read_text(encoding="utf-8")
    hashes = "#"
    while f'"{hashes}' in text or f'"""{hashes}' in text:
        hashes += "#"
    lines.append(f'        "{path.stem}": {hashes}"""')
    lines.extend(text.rstrip("\n").split("\n"))
    lines.append(f'"""{hashes},')
lines += ["    ]", "}", ""]
target.write_text("\n".join(lines), encoding="utf-8")
print(f"wrote {target.relative_to(root)}")
